Shopify.SignInWithShop = Shopify.SignInWithShop || {};
Shopify.SignInWithShop.User = Shopify.SignInWithShop.User || {};
Shopify.SignInWithShop.User.recognized = false;

window.Shopify = window.Shopify || {};
window.Shopify.SignInWithShop = window.Shopify.SignInWithShop || {};
window.Shopify.SignInWithShop.assetMetrics = { sampleRate: 0.01 };
window.Shopify.SignInWithShop.eligible = true;

(function() {
  var isLoaded = false;
  function asyncLoad() {
    if (isLoaded) return;
    isLoaded = true;
    var urls = ["https:\/\/widgets.automizely.com\/returns\/main.js?shop=v8pti0-6j.myshopify.com","https:\/\/cdn.attn.tv\/smith\/dtag.js?shop=v8pti0-6j.myshopify.com","\/\/cdn.shopify.com\/proxy\/a93c3ad86437c2441f84223b2e5409a6f6bf79bcf895e9308a3d4d18d21617c7\/cdn-scripts.signifyd.com\/shopify\/script-tag.js?shop=v8pti0-6j.myshopify.com\u0026sp-cache-control=cHVibGljLCBtYXgtYWdlPTkwMA","https:\/\/cdn.octaneai.com\/shopping-assistant-loader.js?bot_id=ce9vs4tl3bvh849k\u0026ts=1777938175\u0026shop=v8pti0-6j.myshopify.com","https:\/\/app.popfly.com\/api\/scripts\/popfly-affiliate-tracking-v1?shop=v8pti0-6j.myshopify.com","https:\/\/cdn.weglot.com\/weglot_script_tag.js?shop=v8pti0-6j.myshopify.com"];
    for (var i = 0; i < urls.length; i++) {
      var s = document.createElement('script');
      s.type = 'text/javascript';
      s.async = true;
      s.src = urls[i];
      var x = document.getElementsByTagName('script')[0];
      x.parentNode.insertBefore(s, x);
    }
  };
  if(window.attachEvent) {
    window.attachEvent('onload', asyncLoad);
  } else {
    window.addEventListener('load', asyncLoad, false);
  }
})();

if (Shopify.designMode) {
  document.documentElement.classList.add('shopify-design-mode');
}

// Prevent regios app from breaking collection pages on URL change (prevent their navigation checking events)
const originalSetInterval = window.setInterval;
window.setInterval = function (fn, delay, ...args) {
  const stack = new Error().stack || '';
  if (stack.includes('collection_page_discount.js') && fn.toString().includes('window.location.href')) {
    return 0;
  }
  return originalSetInterval(fn, delay, ...args);
};

const originalNavigationAdd = window.navigation.addEventListener;
window.navigation.addEventListener = function (type, listener, options) {
  const stack = new Error().stack || '';
  if (
    stack.includes('collection_page_discount.js') &&
    type === 'navigate' &&
    typeof listener === 'function' &&
    listener.toString().includes('navigationType') &&
    listener.toString().includes('push') &&
    listener.toString().includes('replace')
  ) {
    return;
  }
  return originalNavigationAdd.call(this, type, listener, options);
};

